<?php
declare(strict_types=1);
require_once __DIR__ . '/../modules/auth.php';
require_once __DIR__ . '/../modules/mailer.php';
require_login(); start_app_session();
$user=current_user();$error='';$inviteUrl='';$flash='';$canInvite=app_user_can('team','invite',$user);$canConfigurePermissions=(string)($user['role']??'')==='owner';
if(empty($_SESSION['team_csrf']))$_SESSION['team_csrf']=bin2hex(random_bytes(32));$csrf=$_SESSION['team_csrf'];
$members=tenant_members();
$manageableMembers=array_values(array_filter($members,static fn(array $member):bool=>($member['role']??'')!=='owner'));
$selectedMemberId=(string)($_GET['permissions_user']??$_POST['member_user_id']??($manageableMembers[0]['user_id']??''));
$selectedMember=null;foreach($manageableMembers as $member){if((string)$member['user_id']===$selectedMemberId){$selectedMember=$member;break;}}
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(403);exit('Sessão expirada. Atualize a página.');}
    $postAction=(string)($_POST['action']??'invite');
    if($postAction==='save_permissions'){
        if(!$canConfigurePermissions){http_response_code(403);exit('Somente o proprietário pode configurar permissões da equipe.');}
        try{if(!$selectedMember)throw new DomainException('Selecione um membro válido.');app_permission_save_member(tenant_id(),$selectedMemberId,(array)($_POST['permissions']??[]),(string)$user['id']);$flash='Permissões salvas para '.(string)$selectedMember['name'].'.';}
        catch(DomainException $exception){$error=$exception->getMessage();}
        catch(Throwable $exception){error_log('[AFFILIEY] Falha ao salvar permissões: '.$exception->getMessage());$error='Não foi possível salvar as permissões. Tente novamente.';}
    }elseif($postAction==='reset_permissions'){
        if(!$canConfigurePermissions){http_response_code(403);exit('Somente o proprietário pode configurar permissões da equipe.');}
        if(!$selectedMember){$error='Selecione um membro válido.';}else{try{app_db()->prepare('DELETE FROM membership_permissions WHERE tenant_id=? AND user_id=?')->execute([tenant_id(),$selectedMemberId]);$flash='Permissões padrão do papel restauradas para '.(string)$selectedMember['name'].'.';}catch(Throwable $exception){error_log('[AFFILIEY] Falha ao restaurar permissões: '.$exception->getMessage());$error='Não foi possível restaurar as permissões.';}}
    }else{
        if(!$canInvite){http_response_code(403);exit('Você não tem permissão para convidar membros.');}
        $email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$role=(string)($_POST['role']??'viewer');
        $roleRank=['owner'=>5,'admin'=>4,'manager'=>3,'analyst'=>2,'support'=>2,'viewer'=>1];
        if(!$email||!in_array($role,['admin','manager','analyst','support','viewer'],true))$error='Informe um e-mail válido e um papel permitido.';
        elseif(($roleRank[$role]??0)>($roleRank[(string)($user['role']??'viewer')]??0)&&($user['role']??'')!=='owner')$error='Você só pode convidar membros com um papel igual ou inferior ao seu.';
        else{try{$token=issue_team_invitation(tenant_id(),(string)$email,$role,(string)$user['id']);$inviteUrl=app_public_url().'/accept-invitation.php?token='.rawurlencode($token);if(app_mail_is_configured()){$safeUrl=htmlspecialchars($inviteUrl,ENT_QUOTES,'UTF-8');$tenantName=htmlspecialchars((string)($user['tenant_name']??'seu espaço'),ENT_QUOTES,'UTF-8');$html=app_email_page('Convite para sua equipe','<p>Você foi convidado para acessar o espaço <b>'.$tenantName.'</b> no AFFILIEY.</p><p><a href="'.$safeUrl.'" style="display:inline-block;background:var(--brand-primary-dark);color:#fff;padding:12px 18px;border-radius:8px;text-decoration:none">Aceitar convite</a></p><p>O link expira em sete dias e pode ser usado uma vez.</p>');app_send_email((string)$email,'Convite para equipe — AFFILIEY',$html,"Você foi convidado para acessar o espaço ".($user['tenant_name']??'AFFILIEY').".\n\nAceite o convite usando este link: $inviteUrl\n\nO link expira em sete dias.");$flash='Convite enviado por e-mail. Você também pode copiar o link abaixo.';}else{$flash='Convite criado, mas o e-mail não está configurado. Copie o link e envie para a pessoa.';}}catch(DomainException $exception){$error=$exception->getMessage();}catch(Throwable $exception){$flash='O convite foi criado, mas o e-mail não foi enviado. Copie o link abaixo e confira a configuração SMTP.';error_log('[AFFILIEY] Falha no envio de convite de equipe: '.$exception->getMessage());}}
    }
}
$members=tenant_members();$invitations=tenant_invitations();
foreach($members as $member){if((string)$member['user_id']===$selectedMemberId){$selectedMember=$member;break;}}
$catalog=app_permission_catalog();$memberPermissions=$selectedMember&&$selectedMember['role']!=='owner'?app_member_permissions(tenant_id(),$selectedMember):[];
function te($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$roleNames=['owner'=>'Proprietário','admin'=>'Administrador','manager'=>'Gestor de afiliados','analyst'=>'Analista comercial','support'=>'Suporte','viewer'=>'Leitura'];
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Equipe — AFFILIEY</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/team.css"><script src="assets/js/team.js" defer></script><link rel="stylesheet" href="assets/css/app-theme.css?v=3"><link rel="manifest" href="/manifest.webmanifest"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="default"><link rel="apple-touch-icon" sizes="180x180" href="/brand/affiliey-apple-touch-icon.png"><link rel="stylesheet" href="/assets/css/pwa.css"><script src="/assets/js/pwa.js" defer></script><link rel="icon" type="image/png" href="/brand/affiliey-favicon.png"><link rel="stylesheet" href="/assets/css/brand.css?v=affiliey4"><link rel="stylesheet" href="/assets/css/workspace-premium.css?v=1"><link rel="stylesheet" href="/assets/css/sliding-pill-nav.css?v=2"><script src="/assets/js/sliding-pill-nav.js?v=1" defer></script><link rel="stylesheet" href="/assets/css/responsive-modules.css?v=2"><meta name="theme-color" content="#111827"><meta property="og:site_name" content="AFFILIEY"><meta name="description" content="Gestão de afiliados, vendas, metas e campanhas em uma plataforma."><meta property="og:description" content="Gestão de afiliados, vendas, metas e campanhas em uma plataforma."><meta property="og:type" content="website"><meta property="og:title" content="AFFILIEY | Plataforma de afiliados"><meta property="og:image" content="https://afiliados.horizoncafe.com.br/brand/affiliey-logo-light.png"><link rel="stylesheet" href="/assets/css/page-transitions.css?v=2"><script src="/assets/js/page-transitions.js?v=2" defer></script><link rel="stylesheet" href="/assets/css/typography.css?v=1"></head><body class="app-shell"><header class="topbar"><a class="brand" href="dashboard.php"><picture class="brand-picture"><source media="(max-width: 640px)" srcset="/brand/affiliey-symbol.png"><img class="brand-logo" src="/brand/affiliey-logo-dark.png" alt="AFFILIEY"></picture></a><nav class="main-nav"><?= app_workspace_navigation() ?></nav><div class="top-actions"><?= app_header_account_tools() ?><span><?= te($user['tenant_name']??'') ?></span><a href="login.php?logout=1">Sair</a></div></header><main class="page"><div class="crumb"><a href="dashboard.php">Workspace</a> / Equipe</div><section class="welcome"><div><span class="eyebrow">ESPAÇO DA ORGANIZAÇÃO</span><h1>Equipe e acessos</h1><p>Convide pessoas para trabalhar no espaço <?= te($user['tenant_name']??'') ?>.</p></div></section>
<?php if($flash): ?><div class="notice"><?= te($flash) ?></div><?php endif; ?><?php if($error): ?><div class="notice error"><?= te($error) ?></div><?php endif; ?>
<?php if($inviteUrl): ?><section class="invite-result"><b>Link de convite</b><p>Compartilhe este link com <?= te($_POST['email']??'a pessoa convidada') ?>. Ele expira em 7 dias e só pode ser usado uma vez.</p><div class="copy-row"><input id="inviteLink" readonly value="<?= te($inviteUrl) ?>"><button id="copyInvite" class="button primary" type="button">Copiar link</button></div><?php if(!app_mail_is_configured()): ?><small>Configure o SMTP para enviar convites diretamente por e-mail.</small><?php endif; ?></section><?php endif; ?>
<div class="team-layout"><section class="panel"><div class="panel-head"><div><h2>Membros do espaço</h2><p><?= count($members) ?> pessoa(s) com acesso</p></div></div><div class="table-scroll"><table><thead><tr><th>Pessoa</th><th>Papel</th><th>Desde</th></tr></thead><tbody><?php foreach($members as $member): ?><tr><td><b><?= te($member['name']) ?></b><small><?= te($member['email']) ?></small></td><td><span class="role <?= te($member['role']) ?>"><?= te($roleNames[$member['role']]??$member['role']) ?></span></td><td><?= te(date('d/m/Y',strtotime($member['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<aside class="side"><section class="panel"><div class="panel-head"><div><h2>Convidar para equipe</h2><p>O convite vincula a conta a este espaço.</p></div></div><?php if($canInvite): ?><form method="post"><input type="hidden" name="csrf" value="<?= te($csrf) ?>"><label>E-mail<input type="email" name="email" placeholder="pessoa@empresa.com" required></label><label>Papel<select name="role"><option value="manager">Gestor de afiliados</option><option value="admin">Administrador da organização</option><option value="analyst">Analista comercial — indicadores</option><option value="support">Suporte — sem financeiro</option><option value="viewer">Leitura — consulta</option></select></label><button class="button primary full" type="submit">Criar convite</button></form><?php else: ?><p class="readonly">Somente proprietários e administradores podem convidar membros.</p><?php endif; ?></section>
<section class="panel"><div class="panel-head"><div><h2>Convites pendentes</h2><p>Expiram após 7 dias</p></div></div><?php if(!$invitations): ?><p class="readonly">Nenhum convite pendente.</p><?php else: foreach($invitations as $inv): ?><div class="pending"><span><b><?= te($inv['email']) ?></b><small><?= te($roleNames[$inv['role']]??'') ?> · expira <?= te(date('d/m',strtotime($inv['expires_at']))) ?></small></span><i>Ativo</i></div><?php endforeach; endif; ?></section></aside></div>
<?php if($canConfigurePermissions): ?><section class="panel permission-panel"><div class="panel-head"><div><h2>Permissões por ação</h2><p>Escolha exatamente o que cada membro pode visualizar ou executar. O proprietário mantém controle total.</p></div></div><form method="get" class="permission-member-select"><label for="permissionMember">Membro da equipe</label><select id="permissionMember" name="permissions_user" onchange="this.form.submit()"><option value="">Selecione um membro</option><?php foreach($manageableMembers as $member): ?><option value="<?= te($member['user_id']) ?>" <?= (string)$member['user_id']===$selectedMemberId?'selected':'' ?>><?= te($member['name']) ?> · <?= te($roleNames[$member['role']]??$member['role']) ?></option><?php endforeach; ?></select></form><?php if($selectedMember): ?><p class="permission-note">Papel atual: <b><?= te($roleNames[$selectedMember['role']]??$selectedMember['role']) ?></b>. As seleções abaixo substituem as permissões padrão desse papel.</p><form method="post"><input type="hidden" name="csrf" value="<?= te($csrf) ?>"><input type="hidden" name="action" value="save_permissions"><input type="hidden" name="member_user_id" value="<?= te($selectedMemberId) ?>"><div class="permission-table-wrap"><table class="permission-table"><thead><tr><th>Módulo</th><?php foreach(['view'=>'Visualizar','create'=>'Criar','edit'=>'Editar','delete'=>'Excluir','invite'=>'Convidar','reply'=>'Responder','close'=>'Encerrar'] as $actionKey=>$actionLabel): ?><th><?= te($actionLabel) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($catalog as $moduleKey=>$definition): ?><tr><th scope="row"><?= te($definition['label']) ?></th><?php foreach(['view','create','edit','delete','invite','reply','close'] as $actionKey): ?><td><?php if(isset($definition['actions'][$actionKey])): ?><label class="permission-check"><input type="checkbox" name="permissions[<?= te($moduleKey) ?>][<?= te($actionKey) ?>]" value="1" <?= !empty($memberPermissions[$moduleKey][$actionKey])?'checked':'' ?>><span class="sr-only"><?= te($definition['actions'][$actionKey]) ?> · <?= te($definition['label']) ?></span></label><?php else: ?><span class="permission-na">—</span><?php endif; ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><div class="permission-actions"><button class="button primary" type="submit">Salvar permissões</button></div></form><form method="post" class="permission-reset-form"><input type="hidden" name="csrf" value="<?= te($csrf) ?>"><input type="hidden" name="action" value="reset_permissions"><input type="hidden" name="member_user_id" value="<?= te($selectedMemberId) ?>"><button class="button" type="submit">Restaurar permissões padrão do papel</button></form><?php else: ?><p class="readonly">Convide pessoas para liberar a configuração individual de permissões.</p><?php endif; ?></section><?php endif; ?><section class="roles"><h2>Papéis iniciais</h2><div><article><b>Proprietário</b><p>Controle total. Suas permissões não podem ser removidas.</p></article><article><b>Administrador</b><p>Começa com acesso completo; o proprietário pode ajustar cada ação.</p></article><article><b>Gestor</b><p>Começa com acesso operacional a afiliados, campanhas e recompensas.</p></article><article><b>Leitura</b><p>Começa com acesso somente de consulta.</p></article></div></section></main></body></html>
